function csm_upload(string $field,string $existing=''): string{
    if(!isset($_FILES[$field])||!is_array($_FILES[$field])||(int)($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return $existing;
    $f=$_FILES[$field];if((int)$f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Image upload failed.');
    $size=(int)($f['size']??0);if($size<=0||$size>8*1024*1024)throw new RuntimeException('Image must be 8 MB or smaller.');
    $tmp=(string)$f['tmp_name'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;
    if(!$ext)throw new RuntimeException('Only JPG, PNG or WEBP images are allowed.');
    $dim=@getimagesize($tmp);if(!$dim||($dim[0]??0)<240||($dim[1]??0)<240)throw new RuntimeException('Image must be at least 240 × 240 pixels.');
    $dir=dirname(__DIR__).'/uploads/site-media';if(!is_dir($dir)&&!mkdir($dir,0755,true)&&!is_dir($dir))throw new RuntimeException('Site media folder could not be created.');
    $name='site-'.date('Ymd-His').'-'.bin2hex(random_bytes(5)).'.'.$ext;if(!move_uploaded_file($tmp,$dir.'/'.$name))throw new RuntimeException('Image could not be saved.');
    return 'uploads/site-media/'.$name;
}
function csm_media_src(string $path): string{return '../'.ltrim($path,'/');}
try{
    $pdo=role_portal_db();role_portal_ensure($pdo);pscms_ensure($pdo);security_step17_session_start();
    $user=security_step17_session_user($pdo,true);if(!$user){header('Location: ../login.php');exit;}
    if((int)($user['must_change_password']??0)===1){header('Location: ../change_password.php?required=1');exit;}
    if((string)($user['role_code']??'')!=='admin'){header('Location: access_denied.php');exit;}
    $orgId=pscms_org_id($pdo);$csrf=security_step17_csrf();
    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
        if($action==='save_content'){
            $posted=is_array($_POST['content']??null)?$_POST['content']:[];$allowed=[];foreach($groups as $fields)foreach($fields as $k=>$v)$allowed[$k]=true;
            $s=$pdo->prepare("INSERT INTO public_site_content(organization_id,content_key,content_value,updated_by) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE content_value=VALUES(content_value),updated_by=VALUES(updated_by),updated_at=NOW()");
            foreach($posted as $k=>$v){if(!isset($allowed[$k]))continue;$value=trim((string)$v);if(strlen($value)>8000)throw new RuntimeException('A content field is too long.');$s->execute([$orgId,$k,$value,(int)$user['id']]);}
            security_step17_audit($pdo,(int)$user['id'],'public_site_content_updated','public_site',null,['keys'=>array_keys($posted)]);$success='Customer-site text and contact details updated.';
        }elseif($action==='save_story'){
            $id=(int)($_POST['story_id']??0);$name=trim((string)($_POST['member_name']??''));$headline=trim((string)($_POST['headline']??''));$text=trim((string)($_POST['story_text']??''));$order=max(0,min(9999,(int)($_POST['sort_order']??100)));$status=in_array((string)($_POST['status']??'active'),['active','hidden'],true)?(string)$_POST['status']:'active';$featured=isset($_POST['is_featured'])?1:0;
            if(strlen($name)<2||strlen($text)<10)throw new RuntimeException('Story needs a member name and meaningful story text.');
            $image=csm_upload('story_image',trim((string)($_POST['current_image']??'')));if($image==='')throw new RuntimeException('Choose a story image.');
            if($featured)$pdo->prepare("UPDATE public_site_stories SET is_featured=0 WHERE organization_id=?")->execute([$orgId]);
            if($id>0){$s=$pdo->prepare("UPDATE public_site_stories SET member_name=?,headline=?,story_text=?,image_path=?,sort_order=?,is_featured=?,status=?,updated_by=? WHERE id=? AND organization_id=?");$s->execute([$name,$headline?:null,$text,$image,$order,$featured,$status,(int)$user['id'],$id,$orgId]);}
            else{$s=$pdo->prepare("INSERT INTO public_site_stories(organization_id,member_name,headline,story_text,image_path,sort_order,is_featured,status,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([$orgId,$name,$headline?:null,$text,$image,$order,$featured,$status,(int)$user['id'],(int)$user['id']]);$id=(int)$pdo->lastInsertId();}
            security_step17_audit($pdo,(int)$user['id'],'public_site_story_saved','public_site_story',$id,['status'=>$status,'featured'=>(bool)$featured]);$success='Member story saved and the public story rotation is updated.';
        }elseif($action==='save_service'){
            $id=(int)($_POST['service_id']??0);$name=trim((string)($_POST['service_name']??''));$text=trim((string)($_POST['service_text']??''));$order=max(0,min(9999,(int)($_POST['sort_order']??100)));$status=in_array((string)($_POST['status']??'active'),['active','hidden'],true)?(string)$_POST['status']:'active';
            if(strlen($name)<2||strlen($text)<10)throw new RuntimeException('Service needs a name and description.');
            $image=csm_upload('service_image',trim((string)($_POST['current_image']??'')));if($image==='')throw new RuntimeException('Choose a service image.');
            if($id>0){$s=$pdo->prepare("UPDATE public_site_services SET service_name=?,service_text=?,image_path=?,sort_order=?,status=?,updated_by=? WHERE id=? AND organization_id=?");$s->execute([$name,$text,$image,$order,$status,(int)$user['id'],$id,$orgId]);}
            else{$s=$pdo->prepare("INSERT INTO public_site_services(organization_id,service_name,service_text,image_path,sort_order,status,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?)");$s->execute([$orgId,$name,$text,$image,$order,$status,(int)$user['id'],(int)$user['id']]);$id=(int)$pdo->lastInsertId();}
            security_step17_audit($pdo,(int)$user['id'],'public_site_service_saved','public_site_service',$id,['status'=>$status]);$success='Service saved and the customer Services page is updated.';
        }
    }
    $payload=pscms_payload($pdo);$content=$payload['content'];
    $s=$pdo->prepare("SELECT * FROM public_site_stories WHERE organization_id=? ORDER BY is_featured DESC,sort_order,id");$s->execute([$orgId]);$stories=$s->fetchAll();
    $s=$pdo->prepare("SELECT * FROM public_site_services WHERE organization_id=? ORDER BY sort_order,id");$s->execute([$orgId]);$services=$s->fetchAll();
}catch(Throwable $e){$error=$e->getMessage();}
